import { formatDistanceToNow } from "date-fns";

// Wraps date-fns for the app. The project has moved from date-fns v2 to v4.
//
// v4 notes (verified against date-fns 4.4.0):
// - The package is ESM-first and the modular subpath imports (date-fns/formatDistance)
//   are gone; everything is exported from the root entry point.
// - `formatDistance` still exists, but for "distance from now" the canonical v4
//   function is `formatDistanceToNow`, which reads the current time from the
//   library's own clock (and honours the `in` timezone context), so it is less
//   prone to the clock-skew/argument-order issues of the old v2 pattern.
// - v4 normalizes mixed date types, but still throws RangeError on invalid dates;
//   we validate explicitly so the wrapper's contract is stable across versions.
export function postedAt(dateLike) {
  const posted = new Date(dateLike);

  if (!Number.isFinite(posted.getTime())) {
    throw new RangeError(`postedAt: invalid date received: ${dateLike}`);
  }

  return formatDistanceToNow(posted, { addSuffix: true });
}

