import { formatDistanceToNow } from "date-fns";

// Wraps date-fns for the app. The project has moved from date-fns v2 to v4
// (see TASK.md). Verified against date-fns 4.4.0:
//
// - v4 is ESM-first ("type": "module"), so the root import works in Node ESM;
//   per-function subpath imports (date-fns/formatDistance) still exist.
// - `formatDistance` is NOT removed or renamed in v4, so the old v2 call still
//   worked after the upgrade. The real improvement is to use the "ToNow"
//   variant: `formatDistanceToNow` reads the current time internally instead of
//   requiring `new Date()` as the second argument, which removes the
//   argument-order/clock-skew foot-gun of the v2 pattern and supports the v4
//   `in` timezone context.
// - v4 normalizes mixed date inputs but still throws on invalid dates; we
//   validate explicitly so the wrapper's contract is version-independent.
export function postedAt(dateLike) {
  const posted = new Date(dateLike);

  if (!Number.isFinite(posted.getTime())) {
    throw new RangeError(`postedAt: invalid date received: ${dateLike}`);
  }

  return formatDistanceToNow(posted, { addSuffix: true });
}

